/// An object event's trainer-battle behaviour, matching the upstream
/// `TRAINER_TYPE_*` identifiers
/// (`pokeemerald/include/constants/trainer_types.h`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum TrainerType {
    None = 0,
    Normal = 1,
    SeeAllDirections = 2,
    Buried = 3,
}

impl TrainerType {
    /// The upstream `TRAINER_TYPE_*` id for this value.
    #[must_use]
    pub const fn id(self) -> u8 {
        self as u8
    }

    /// Resolve an upstream `TRAINER_TYPE_*` id into a [`TrainerType`].
    ///
    /// # Errors
    ///
    /// Returns [`AssetError::UnknownTrainerType`] if `id` is not one of the modelled values.
    pub const fn from_id(id: u8) -> Result<Self, AssetError> {
        match id {
            0 => Ok(Self::None),
            1 => Ok(Self::Normal),
            2 => Ok(Self::SeeAllDirections),
            3 => Ok(Self::Buried),
            other => Err(AssetError::UnknownTrainerType(other)),
        }
    }
}

