    #[test]
    fn upstream_tie_trainer_movement_and_sight() {
        // AbandonedShip_Corridors_1F's Charlie: a normal trainer with a
        // sight range of 3 and an unusual 4x7 patrol range.
        let table = MapEventsTable::new();
        let e = table
            .events(MapId("MAP_ABANDONED_SHIP_CORRIDORS_1F"))
            .unwrap();
        let charlie = e
            .object_events
            .iter()
            .find(|o| o.script == "AbandonedShip_Corridors_1F_EventScript_Charlie")
            .expect("Charlie");
        assert_eq!(charlie.trainer_type, TrainerType::Normal);
        assert_eq!(charlie.trainer_sight_or_berry_tree_id, "3");
        assert_eq!(
            charlie.movement_type,
            MovementType::WalkSequenceUpLeftDownRight
        );
        assert_eq!((charlie.movement_range_x, charlie.movement_range_y), (4, 7));
    }

    #[test]
    fn shared_events_map_resolves_for_all_aliases() {
        // The eleven contest-hall aliases all carry empty event lists of
        // their own and resolve, through `resolve`, to ContestHall's.
        let table = MapEventsTable::new();
        let aliases = [
            "MAP_CONTEST_HALL_BEAUTY",
            "MAP_CONTEST_HALL_COOL",
            "MAP_CONTEST_HALL_CUTE",
            "MAP_CONTEST_HALL_SMART",
            "MAP_CONTEST_HALL_TOUGH",
            "MAP_UNUSED_CONTEST_HALL1",
            "MAP_UNUSED_CONTEST_HALL2",
            "MAP_UNUSED_CONTEST_HALL3",
            "MAP_UNUSED_CONTEST_HALL4",
            "MAP_UNUSED_CONTEST_HALL5",
            "MAP_UNUSED_CONTEST_HALL6",
        ];
        let contest_hall = table.events(MapId("MAP_CONTEST_HALL")).unwrap();
        assert_eq!(contest_hall.shared_events_map, None);
        assert_eq!(contest_hall.object_events.len(), 15);

        let mut alias_count = 0;
        for alias in aliases {
            let own = table.events(MapId(alias)).unwrap();
            assert_eq!(own.shared_events_map, Some(MapId("MAP_CONTEST_HALL")));
            assert!(own.object_events.is_empty());

            let resolved = table.resolve(MapId(alias)).unwrap();
            assert_eq!(resolved.id, MapId("MAP_CONTEST_HALL"));
            assert_eq!(resolved.object_events.len(), 15);
            alias_count += 1;
        }
        assert_eq!(alias_count, 11);

        // A map with no indirection resolves to itself.
        let direct = table.resolve(MapId("MAP_LITTLEROOT_TOWN")).unwrap();
        assert_eq!(direct.id, MapId("MAP_LITTLEROOT_TOWN"));
    }

    #[test]
    fn every_map_id_is_unique() {
        let table = MapEventsTable::new();
        let ids: Vec<_> = table.iter().map(|e| e.id).collect();
        let unique: std::collections::HashSet<_> = ids.iter().collect();
        assert_eq!(ids.len(), unique.len(), "duplicate MapId in table");
    }

    #[test]
    fn warp_static_destinations_name_a_real_map_header() {
        // Every warp whose destination is a real map (not the MAP_DYNAMIC
        // sentinel) names a map that actually has an entry in this table —
        // i.e. no warp points at a nonexistent map.
        let table = MapEventsTable::new();
        let mut checked_static = 0;
        let mut checked_dynamic = 0;
        for e in table.iter() {
            for w in e.warp_events {
                match w.dest_map {
                    WarpDestination::Map(dest) => {
                        assert!(
                            table.get(dest).is_some(),
                            "warp in {:?} points at unknown map {:?}",
                            e.id,
                            dest
                        );
                        checked_static += 1;
                    }
                    WarpDestination::Dynamic => checked_dynamic += 1,
                }
            }
        }
        assert!(checked_static > 0);
        assert!(checked_dynamic > 0);
    }

    #[test]
    fn dynamic_warp_ids_only_pair_with_the_dynamic_destination() {
        // In this checkout, WARP_ID_DYNAMIC/WARP_ID_SECRET_BASE always
        // co-occur with a MAP_DYNAMIC destination (never a real map) — this
        // pins that observed invariant so a future regeneration would flag
        // if it ever stopped holding.
        let table = MapEventsTable::new();
        for e in table.iter() {
            for w in e.warp_events {
                if !matches!(w.dest_warp_id, WarpId::Fixed(_)) {
                    assert_eq!(w.dest_map, WarpDestination::Dynamic);
                }
            }
        }
    }

    #[test]
    fn event_kind_counts_match_extraction_totals() {
        // Structural guard over the whole table: totals line up with what
        // the generator reported at extraction time (2,776 object events,
        // 1,313 warps, 375 coord events, 720 bg events).
        let table = MapEventsTable::new();
        let mut obj = 0usize;
        let mut warp = 0usize;
        let mut coord = 0usize;
        let mut bg = 0usize;
        let mut shared = 0usize;
        for e in table.iter() {
            obj += e.object_events.len();
            warp += e.warp_events.len();
            coord += e.coord_events.len();
            bg += e.bg_events.len();
            if e.shared_events_map.is_some() {
                shared += 1;
                assert!(e.object_events.is_empty());
                assert!(e.warp_events.is_empty());
                assert!(e.coord_events.is_empty());
                assert!(e.bg_events.is_empty());
            }
        }
        assert_eq!(obj, 2776);
        assert_eq!(warp, 1313);
        assert_eq!(coord, 375);
        assert_eq!(bg, 720);
        assert_eq!(shared, 11);
    }

    #[test]
    fn every_object_event_local_id_matches_its_position() {
        let table = MapEventsTable::new();
        for e in table.iter() {
            for (i, o) in e.object_events.iter().enumerate() {
                assert_eq!(o.local_id as usize, i + 1);
            }
        }
    }

    #[test]
    fn movement_type_id_round_trips() {
        for id in 0u8..=0x50 {
            let m = MovementType::from_id(id).unwrap();
            assert_eq!(m.id(), id);
        }
        assert_eq!(
            MovementType::from_id(0x51),
            Err(AssetError::UnknownMovementType(0x51))
        );
    }

    #[test]
    fn trainer_type_id_round_trips() {
        for id in 0u8..=3 {
            let t = TrainerType::from_id(id).unwrap();
            assert_eq!(t.id(), id);
        }
        assert_eq!(
            TrainerType::from_id(4),
            Err(AssetError::UnknownTrainerType(4))
        );
    }

